/**
 * Checks the Android project generated by `expo prebuild` (no Android SDK
 * needed): SDK downloads are disabled, INTERNET is the only permission kept,
 * backups are off, the network security configs are the expected ones, the
 * fonts are embedded, the app name matches the flavour (ADR 0011), the NDK
 * and CMake are the pinned runner packages and release builds can only be
 * signed with the per-run CI key.
 *
 *   node apps/android/scripts/check-native-project.ts <android-dir> <demo|production>
 */
import { readFileSync, readdirSync } from 'node:fs'
import path from 'node:path'
import { DEMO_PRODUCT_NAME } from '@cindl/contracts'
import { nativeFontFiles } from '@cindl/tokens'
import {
  DEBUG_NETWORK_SECURITY_CONFIG,
  RELEASE_NETWORK_SECURITY_CONFIG,
} from '../plugins/withNetworkSecurity.ts'
import { DATA_EXTRACTION_RULES } from '../plugins/withNoBackups.ts'
import { SDK_DOWNLOAD_PROPERTY } from '../plugins/withNoSdkDownloads.ts'
import { TOOLCHAIN_MARKER } from '../plugins/withAndroidToolchain.ts'
import { TEST_SIGNING_MARKER } from '../plugins/withTestSigning.ts'
import { CMAKE_VERSION, NDK_VERSION } from '../sdk/android-sdk.ts'

const [root, flavour] = process.argv.slice(2)
if (!root || (flavour !== 'demo' && flavour !== 'production')) {
  console.error('Usage: check-native-project.ts <android-dir> <demo|production>')
  process.exit(2)
}
const read = (file: string) => readFileSync(path.join(root, file), 'utf8')
const problems: string[] = []
const expect = (ok: boolean, problem: string) => {
  if (!ok) problems.push(problem)
}

const properties = read('gradle.properties')
  .split('\n')
  .map((line) => line.trim())
  .filter((line) => line.startsWith(`${SDK_DOWNLOAD_PROPERTY}=`))
expect(
  properties.length === 1 && properties[0] === `${SDK_DOWNLOAD_PROPERTY}=false`,
  `gradle.properties must set ${SDK_DOWNLOAD_PROPERTY}=false exactly once (found: ${properties.join(', ') || 'none'})`,
)

const rootGradle = read('build.gradle')
expect(
  rootGradle.includes(TOOLCHAIN_MARKER) &&
    rootGradle.includes(`ext.ndkVersion = '${NDK_VERSION}'`) &&
    rootGradle.includes(`cmake.version = '${CMAKE_VERSION}'`) &&
    rootGradle.indexOf(TOOLCHAIN_MARKER) <
      rootGradle.indexOf('apply plugin: "expo-root-project"'),
  `build.gradle does not pin NDK ${NDK_VERSION} and CMake ${CMAKE_VERSION} before Expo's root plugin`,
)
const appGradle = read('app/build.gradle')
expect(
  appGradle.includes(TEST_SIGNING_MARKER) &&
    appGradle
      .slice(appGradle.indexOf('release {'))
      .includes(
        "signingConfig(System.getenv('CINDL_TEST_KEYSTORE') ? signingConfigs.cindlTest : null)",
      ) &&
    !/release \{[^}]*signingConfig signingConfigs\.debug/.test(appGradle),
  'release builds could be signed with the public debug key',
)

const manifest = read('app/src/main/AndroidManifest.xml')
const permissions = [...manifest.matchAll(/<uses-permission ([^>]*?)\/>/g)].map(
  (m) => m[1] ?? '',
)
for (const permission of permissions) {
  const name = /android:name="([^"]+)"/.exec(permission)?.[1]
  const removed = permission.includes('tools:node="remove"')
  expect(
    name === 'android.permission.INTERNET' ? !removed : removed,
    `unexpected permission entry: ${permission}`,
  )
}
expect(
  permissions.some(
    (p) => p.includes('android.permission.INTERNET') && !p.includes('remove'),
  ),
  'INTERNET permission missing',
)
expect(manifest.includes('android:allowBackup="false"'), 'allowBackup is not false')
expect(
  manifest.includes('android:dataExtractionRules="@xml/data_extraction_rules"') &&
    read('app/src/main/res/xml/data_extraction_rules.xml') === DATA_EXTRACTION_RULES,
  'backup and device-transfer exclusions are missing',
)
expect(
  manifest.includes('android:networkSecurityConfig="@xml/network_security_config"'),
  'network security config is not wired into the manifest',
)
expect(
  read('app/src/main/res/xml/network_security_config.xml') ===
    RELEASE_NETWORK_SECURITY_CONFIG,
  'release network security config differs from the plugin',
)
expect(
  read('app/src/debug/res/xml/network_security_config.xml') ===
    DEBUG_NETWORK_SECURITY_CONFIG,
  'debug network security config differs from the plugin',
)

const fonts = new Set(readdirSync(path.join(root, 'app/src/main/assets/fonts')))
for (const file of nativeFontFiles)
  expect(fonts.has(path.basename(file)), `font not embedded: ${path.basename(file)}`)

const appName = /<string name="app_name">([^<]*)<\/string>/.exec(
  read('app/src/main/res/values/strings.xml'),
)?.[1]
const expected = flavour === 'demo' ? DEMO_PRODUCT_NAME : 'Cindl'
expect(appName === expected, `app name is ${appName ?? 'missing'}, expected ${expected}`)

if (problems.length) {
  for (const problem of problems) console.error(`- ${problem}`)
  process.exit(1)
}
console.log(
  `OK: ${flavour} native project (no SDK downloads, pinned NDK and CMake, CI-key signing, INTERNET only, backups off)`,
)
